'use strict';

// Injects the live `dbml-diff --help` output into docs/cli.md, between the
// AUTO-GENERATED markers, so the flag reference cannot drift from the CLI.
//
//   node scripts/build-cli-docs.js          rewrite docs/cli.md in place
//   node scripts/build-cli-docs.js --check   exit 1 if docs/cli.md is stale
//
// The --check mode is what CI and the docs test use to fail on drift.

const fs = require('fs');
const path = require('path');
const { spawnSync } = require('child_process');

const BIN = path.join(__dirname, '..', 'bin', 'dbml-diff.js');
const DOC = path.join(__dirname, '..', 'docs', 'cli.md');
const BEGIN = '<!-- BEGIN dbml-diff --help (auto-generated by scripts/build-cli-docs.js) -->';
const END = '<!-- END dbml-diff --help -->';

function helpBlock() {
  const res = spawnSync(process.execPath, [BIN, '--help'], { encoding: 'utf8' });
  if (res.status !== 0) {
    throw new Error(`dbml-diff --help exited ${res.status}: ${res.stderr}`);
  }
  return `${BEGIN}\n\`\`\`\n${res.stdout.trimEnd()}\n\`\`\`\n${END}`;
}

// Replace whatever currently sits between the markers with a freshly rendered
// block. Returns the new file contents.
function inject(current, block) {
  const start = current.indexOf(BEGIN);
  const end = current.indexOf(END);
  if (start === -1 || end === -1 || end < start) {
    throw new Error(`docs/cli.md is missing the AUTO-GENERATED markers`);
  }
  return current.slice(0, start) + block + current.slice(end + END.length);
}

function main() {
  const check = process.argv.includes('--check');
  const current = fs.readFileSync(DOC, 'utf8');
  const next = inject(current, helpBlock());
  if (check) {
    if (current !== next) {
      process.stderr.write('docs/cli.md is out of date; run: node scripts/build-cli-docs.js\n');
      process.exit(1);
    }
    return;
  }
  if (current !== next) {
    fs.writeFileSync(DOC, next);
    process.stdout.write('docs/cli.md updated\n');
  } else {
    process.stdout.write('docs/cli.md already up to date\n');
  }
}

main();
